<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {api} from '../api';import type {WorkTab} from '../stores';import Modal from './Modal.vue';
const props=defineProps<{tab:WorkTab}>(),emit=defineEmits<{cancel:[];saved:[code:string]}>();
const form=ref<any>({employee_code:'',employee_name:'',from_store_id:'',to_store_id:'',notes:'',continue_acting:undefined}),acting=ref(false),detecting=ref(false),baseline=JSON.stringify(form.value),catalog=ref<any>(null),loading=ref(false),error=ref(''),search=ref(''),confirm=ref(false),cancel=ref(false);
let requestId='',pending='';props.tab.submitOnly=true;
watch(form,()=>props.tab.dirty=JSON.stringify(form.value)!==baseline,{deep:true,flush:'sync'});
const matches=computed(()=>search.value.trim()?(catalog.value?.employees||[]).filter((e:any)=>[e.employee_code,e.employee_name].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())).slice(0,30):[]);
function store(id:string){const s=catalog.value?.stores.find((s:any)=>s.id===id);return s?`${s.store_code} ${s.store_name}`:'未指定或已停用門市';}
function pick(e:any){form.value.employee_code=e.employee_code;form.value.employee_name=e.employee_name;if(catalog.value.stores.some((s:any)=>s.id===e.store_id))form.value.from_store_id=e.store_id;else form.value.from_store_id='';search.value='';}
async function load(){loading.value=true;error.value='';try{catalog.value=await api('transfers/create');}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
// H.5：選好員工與原店後自動偵測是否為代理店長；是的話必須回答「新任職的門市是否也擔任代理店長」。
let detectSeq=0;
watch(()=>[form.value.employee_code,form.value.from_store_id],async()=>{const seq=++detectSeq,code=form.value.employee_code.trim().toUpperCase();acting.value=false;form.value.continue_acting=undefined;detecting.value=false;if(!/^[A-Z0-9_-]{1,20}$/.test(code)||!form.value.from_store_id)return;detecting.value=true;try{const r=await api('transfers/create?acting_code='+encodeURIComponent(code)+'&from_store_id='+form.value.from_store_id);if(seq===detectSeq)acting.value=!!r.acting;}catch{if(seq===detectSeq)acting.value=false;}finally{if(seq===detectSeq)detecting.value=false;}});
function review(){error.value='';if(detecting.value){error.value='正在確認此員工是否為代理店長，請稍候再送出';return;}if(acting.value&&typeof form.value.continue_acting!=='boolean'){error.value='此員工目前是代理店長，請回答新任職的門市是否也擔任代理店長';return;}if(form.value.from_store_id===form.value.to_store_id){error.value='原任職門市與新任職門市不能相同';return;}confirm.value=true;}
function close(){if(props.tab.dirty)cancel.value=true;else emit('cancel');}
async function save(){if(props.tab.busy)return;confirm.value=false;props.tab.busy=true;error.value='';const data:any={...form.value};if(!acting.value)delete data.continue_acting;const key=JSON.stringify(data);if(key!==pending){pending=key;requestId=crypto.randomUUID();}try{await api('transfers/create',{method:'POST',body:JSON.stringify({requestId,data})});props.tab.dirty=false;emit('saved',data.employee_code.trim().toUpperCase());}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
onMounted(load);onBeforeUnmount(()=>{delete props.tab.submitOnly;});
</script>
<template><section class="transfer-create"><h2>新增調店申請</h2><p>送出後等待原店或新店任一位督導確認生效日期。</p><p v-if="loading" role="status">正在載入門市與員工…</p><p v-if="error" class="notice error" role="alert">{{error}}</p><button v-if="!catalog&&!loading" @click="load">重新載入</button>
<form v-if="catalog" @submit.prevent="review"><fieldset :disabled="tab.busy||confirm"><label>查找員工<input v-model="search" autocomplete="off" placeholder="輸入員編或姓名帶入資料"></label><div v-if="search.trim()" class="matches"><button v-for="e in matches" :key="e.id" type="button" @click="pick(e)">{{e.employee_code}} {{e.employee_name}} · {{store(e.store_id)}}</button><p v-if="!matches.length">沒有符合的員工，可在下方填寫員編與姓名。</p><small v-if="matches.length===30">顯示前30筆，請輸入更完整的員編或姓名。</small></div>
<div class="fields"><label>員編<input v-model="form.employee_code" required maxlength="20" pattern="[A-Za-z0-9_\-]+" autocomplete="off"></label><label>姓名<input v-model="form.employee_name" required maxlength="100"></label><label>原任職門市<select aria-label="原任職門市" v-model="form.from_store_id" required><option value="">請選擇</option><option v-for="s in catalog.stores" :key="s.id" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label><label>新任職門市<select aria-label="新任職門市" v-model="form.to_store_id" required><option value="">請選擇</option><option v-for="s in catalog.stores" :key="s.id" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label></div><fieldset v-if="acting" class="acting-question" data-testid="acting-question"><legend>此員工目前是代理店長：新任職的門市是否也擔任代理店長？</legend><label class="inline"><input type="radio" name="continue-acting" :value="true" v-model="form.continue_acting" aria-label="新店續任代理店長：是"> 是（調店生效時自動在新店登記代理店長異動）</label><label class="inline"><input type="radio" name="continue-acting" :value="false" v-model="form.continue_acting" aria-label="新店續任代理店長：否"> 否（代理註記隨調店結束）</label></fieldset><label>備註<textarea v-model="form.notes" rows="3" maxlength="5000"></textarea></label><div class="dialog-actions"><button type="button" @click="close">取消新增</button><button type="submit" class="primary" :disabled="detecting">{{tab.busy?'正在送出…':detecting?'確認代理身分中…':'核對並送出'}}</button></div></fieldset></form><button v-if="!catalog" :disabled="loading" @click="close">取消新增</button>
<Modal v-if="confirm" title="確認調店申請" @cancel="confirm=false"><p>{{form.employee_code}} {{form.employee_name}}</p><p>{{store(form.from_store_id)}} → {{store(form.to_store_id)}}</p><p v-if="acting" data-testid="acting-answer">新店續任代理店長：{{form.continue_acting?'是':'否'}}</p><p class="notes">{{form.notes||'未填寫備註'}}</p><div class="dialog-actions"><button @click="confirm=false">返回修改</button><button class="primary" @click="save">確認送出</button></div></Modal>
<Modal v-if="cancel" title="放棄調店申請草稿" @cancel="cancel=false"><p>尚未送出的 {{form.employee_code}} {{form.employee_name}} 申請內容將被清除。</p><div class="dialog-actions"><button @click="cancel=false">繼續填寫</button><button class="danger" @click="tab.dirty=false;emit('cancel')">放棄草稿</button></div></Modal>
</section></template>
<style scoped>.transfer-create{max-width:900px;padding:24px 0;border-block:1px solid var(--line);margin:24px 0}fieldset{border:0;padding:0;min-width:0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}label{display:grid;gap:8px}input,select,textarea{width:100%;min-width:0}.matches{display:grid;gap:4px;max-height:240px;overflow:auto;margin-top:8px}.matches button{text-align:left;white-space:normal}.notes{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:600px){.fields{grid-template-columns:1fr}}.acting-question{border:1px solid var(--line);padding:12px 16px;margin:16px 0}.acting-question .inline{display:flex;gap:8px;align-items:center;margin-top:8px}.acting-question input{width:auto}</style>

